/*Table structure for table `auth_permissions` */

CREATE TABLE `auth_permissions` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `description` varchar(255) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb3;

/*Data for the table `auth_permissions` */

insert  into `auth_permissions`(`id`,`name`,`description`) values (1,'manage-user','Manage All User');
insert  into `auth_permissions`(`id`,`name`,`description`) values (2,'manage-profile','Manage User Profile');

/*Table structure for table `auth_reset_attempts` */

CREATE TABLE `auth_reset_attempts` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `email` varchar(255) NOT NULL,
  `ip_address` varchar(255) NOT NULL,
  `user_agent` varchar(255) NOT NULL,
  `token` varchar(255) DEFAULT NULL,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

/*Data for the table `auth_reset_attempts` */

/*Table structure for table `auth_tokens` */

CREATE TABLE `auth_tokens` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `selector` varchar(255) NOT NULL,
  `hashedValidator` varchar(255) NOT NULL,
  `user_id` int unsigned NOT NULL,
  `expires` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `auth_tokens_user_id_foreign` (`user_id`),
  KEY `selector` (`selector`),
  CONSTRAINT `auth_tokens_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

/*Data for the table `auth_tokens` */

/*Table structure for table `auth_users_permissions` */

CREATE TABLE `auth_users_permissions` (
  `user_id` int unsigned NOT NULL DEFAULT '0',
  `permission_id` int unsigned NOT NULL DEFAULT '0',
  KEY `auth_users_permissions_permission_id_foreign` (`permission_id`),
  KEY `user_id_permission_id` (`user_id`,`permission_id`),
  CONSTRAINT `auth_users_permissions_permission_id_foreign` FOREIGN KEY (`permission_id`) REFERENCES `auth_permissions` (`id`) ON DELETE CASCADE,
  CONSTRAINT `auth_users_permissions_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

/*Data for the table `auth_users_permissions` */

/*Table structure for table `kredit` */

CREATE TABLE `kredit` (
  `id` int NOT NULL AUTO_INCREMENT,
  `stts_pnd` varchar(255) DEFAULT NULL,
  `produk` varchar(30) NOT NULL,
  `plafon` bigint NOT NULL,
  `jangka` bigint NOT NULL,
  `tgl_daftar` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `tgl_survey` date DEFAULT NULL,
  `tgl_komite` date DEFAULT NULL,
  `tgl_realisasi` date DEFAULT NULL,
  `id_petugas` int NOT NULL,
  `nama_petugas` varchar(255) DEFAULT NULL,
  `proses` varchar(255) DEFAULT NULL,
  `status` varchar(255) DEFAULT NULL,
  `nama_pem` varchar(255) DEFAULT NULL,
  `jenis_pem` varchar(255) DEFAULT NULL,
  `nama_pang` varchar(255) DEFAULT NULL,
  `ttl1` text,
  `no_ktp` bigint DEFAULT NULL,
  `foto_ktp` varchar(255) DEFAULT NULL,
  `mas_ber` varchar(255) DEFAULT NULL,
  `nama_ibu` varchar(255) DEFAULT NULL,
  `pend_ter` varchar(255) DEFAULT NULL,
  `profesi` varchar(255) DEFAULT NULL,
  `usaha` varchar(255) DEFAULT NULL,
  `status_kaw` varchar(255) DEFAULT NULL,
  `jumlah_tang` varchar(255) DEFAULT NULL,
  `no_telp` varchar(255) DEFAULT NULL,
  `nama_pas` varchar(255) DEFAULT NULL,
  `status_pas` varchar(255) DEFAULT NULL,
  `ttl_pas` varchar(255) DEFAULT NULL,
  `no_ktp2` bigint DEFAULT NULL,
  `jenis_pas` varchar(255) DEFAULT NULL,
  `masa_ber2` varchar(255) DEFAULT NULL,
  `pend_ter2` varchar(255) DEFAULT NULL,
  `profesi2` varchar(255) DEFAULT NULL,
  `usaha2` varchar(255) DEFAULT NULL,
  `no_telp2` varchar(255) DEFAULT NULL,
  `jl` text,
  `rtrw` text,
  `kec` varchar(255) DEFAULT NULL,
  `kab` varchar(255) DEFAULT NULL,
  `no_telp3` bigint DEFAULT NULL,
  `kopos` bigint DEFAULT NULL,
  `hp` bigint DEFAULT NULL,
  `status_ting` varchar(255) DEFAULT NULL,
  `lama` bigint DEFAULT NULL,
  `jl2` text,
  `rtrw2` text,
  `kec2` varchar(255) DEFAULT NULL,
  `kab2` varchar(255) DEFAULT NULL,
  `no_telp4` bigint DEFAULT NULL,
  `kopos2` bigint DEFAULT NULL,
  `tipe` varchar(255) DEFAULT NULL,
  `nama_badan` varchar(255) DEFAULT NULL,
  `jenis_keg` varchar(255) DEFAULT NULL,
  `bidang` varchar(255) DEFAULT NULL,
  `alamat` text,
  `kel` varchar(255) DEFAULT NULL,
  `rtrw3` text,
  `kec3` varchar(255) DEFAULT NULL,
  `kab3` varchar(255) DEFAULT NULL,
  `no_telp5` bigint DEFAULT NULL,
  `npwp` text,
  `siup` text,
  `lama2` bigint DEFAULT NULL,
  `omset` bigint DEFAULT NULL,
  `laba` bigint DEFAULT NULL,
  `informasi` varchar(255) DEFAULT NULL,
  `foto_agunan` varchar(255) DEFAULT NULL,
  `tujuan` varchar(255) DEFAULT NULL,
  `angsuran` bigint DEFAULT NULL,
  `takover` varchar(255) DEFAULT NULL,
  `bank` varchar(255) DEFAULT NULL,
  `ttd_daftar` varchar(255) DEFAULT NULL,
  `ttd_petugas` varchar(255) DEFAULT NULL,
  `ttd_slick` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `id_petugas` (`id_petugas`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

/*Data for the table `kredit` */

/*Table structure for table `kunker` */

CREATE TABLE `kunker` (
  `id` int NOT NULL AUTO_INCREMENT,
  `id_petugas` int NOT NULL,
  `tanggal_bertamu` datetime DEFAULT CURRENT_TIMESTAMP,
  `nama_petugas` varchar(255) DEFAULT NULL,
  `nama_debitur` varchar(255) DEFAULT NULL,
  `alamat` text,
  `tujuan` varchar(255) DEFAULT NULL,
  `hasil` text,
  `gamlap` longtext,
